import{_ as a,o as r,c as t,a3 as o}from"./chunks/framework.g9mfNVRQ.js";const h=JSON.parse('{"title":"Comment utiliser cette documentation ?","description":"","frontmatter":{"source_hash":"02a52b4234","source_commit":"4613ad5"},"headers":[],"relativePath":"fr/install/usethedoc.md","filePath":"fr/install/usethedoc.md"}'),n={name:"fr/install/usethedoc.md"};function i(s,e,u,l,c,p){return r(),t("div",null,[...e[0]||(e[0]=[o('<p>Cette documentation est basée sur la <a href="https://github.com/NightscoutFoundation/xDrip/releases" target="_blank" rel="noreferrer">dernière Nightly Build</a> (comptez quelques jours de décalage après une publication).</p><h2 id="if-youre-completely-new-to-xdrip" tabindex="-1"><strong>Si vous découvrez xDrip</strong> <a class="header-anchor" href="#if-youre-completely-new-to-xdrip" aria-label="Permalink to &quot;**Si vous découvrez xDrip** {#if-youre-completely-new-to-xdrip}&quot;">​</a></h2><p>Pour une première installation, continuez vers ⇒ <a href="./prerequisites.html">prérequis</a> et suivez le parcours.</p><h2 id="if-youre-already-using-xdrip" tabindex="-1"><strong>Si vous utilisez déjà xDrip</strong> <a class="header-anchor" href="#if-youre-already-using-xdrip" aria-label="Permalink to &quot;**Si vous utilisez déjà xDrip** {#if-youre-already-using-xdrip}&quot;">​</a></h2><p>Si une fonction décrite ici n&#39;apparaît pas dans votre application, vous devez peut-être <a href="./../use/update.html">mettre à jour</a> xDrip.<br> La version pour laquelle chaque page a été rédigée est indiquée en bas de page : une version plus ancienne peut ne pas inclure la fonction.</p><br><div class="info custom-block"><p class="custom-block-title">Info</p><p>Les fonctions du mode ingénieur ne sont volontairement pas documentées.</p></div><br><h3 id="original-documentation" tabindex="-1">Documentation d&#39;origine <a class="header-anchor" href="#original-documentation" aria-label="Permalink to &quot;Documentation d&#39;origine {#original-documentation}&quot;">​</a></h3><p>Cette documentation rassemble plusieurs sources : lorsque c&#39;est le cas, vous trouverez des liens vers la <strong>documentation d&#39;origine et de référence</strong>.<br> Fiez-vous toujours à la documentation d&#39;origine, sauf si elle est obsolète (ce sera indiqué).</p><h3 id="translation" tabindex="-1">Traduction <a class="header-anchor" href="#translation" aria-label="Permalink to &quot;Traduction {#translation}&quot;">​</a></h3><p>La documentation est disponible en anglais, en français et en italien. Utilisez le sélecteur de langue en haut de la page pour changer de langue : vous restez sur la même page.<br> Les traductions sont en cours : les pages pas encore traduites s&#39;affichent en anglais, avec un avertissement. L&#39;anglais est la version de référence ; une page traduite dont la version anglaise a changé depuis est signalée.</p><p>Les noms des menus et des paramètres sont ceux affichés par xDrip en français. Si votre xDrip est en anglais, la <a href="./../../install/usethedoc.html">version anglaise</a> de la documentation vous sera plus facile à suivre.</p><h3 id="search" tabindex="-1">Recherche <a class="header-anchor" href="#search" aria-label="Permalink to &quot;Recherche {#search}&quot;">​</a></h3><p>Vous pouvez rechercher un menu ou un terme dans la documentation avec la loupe en haut à droite, dans la langue que vous lisez.</p><h3 id="typo-error-missing-information" tabindex="-1">Faute, erreur, information manquante <a class="header-anchor" href="#typo-error-missing-information" aria-label="Permalink to &quot;Faute, erreur, information manquante {#typo-error-missing-information}&quot;">​</a></h3><p>Vos retours sont les bienvenus : ouvrez un <a href="https://github.com/xdrip/xdrip_docs/issues" target="_blank" rel="noreferrer">ticket (issue)</a> sur GitHub.</p><p>Vous pouvez aussi contribuer en créant une <a href="https://github.com/xdrip/xdrip_docs/pulls" target="_blank" rel="noreferrer">pull request</a> dans le dépôt principal.</p><p>Vous pouvez également donner votre avis dans le groupe Facebook principal <a href="https://www.facebook.com/groups/xDripG5" target="_blank" rel="noreferrer">xDrip</a> (GitHub reste recommandé).</p><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases" target="_blank" rel="noreferrer"><em>Dernière modification</em></a></p>',21)])])}const m=a(n,[["render",i]]);export{h as __pageData,m as default};
